basicCode.vanilla:
import { createConnectionState } from '@/components/ui/connection-state';

createConnectionState({
  state: 'reconnecting',
  countdown: 'em 5 s',
  labels: rotulos,
  onRetry: () => religar(),
});

basicCode.react:
import { ConnectionState } from "@/components/ui/connection-state";

<ConnectionState
  state="reconnecting"
  countdown="em 5 s"
  labels={rotulos}
  onRetry={() => religar()}
/>

withLabelsCode.web:
// A palavra de cada um dos três estados, e o rótulo da ação onde ela existe.
//
// Ligado fica sem ação de propósito: sobre uma ligação de pé não há o que
// fazer aqui. Os outros dois têm nomes diferentes porque fazem coisas
// diferentes — um apressa a tentativa que já está marcada, o outro começa uma.
const rotulos = {
  state: {
    connected: 'Ligado',
    reconnecting: 'Reconectando',
    disconnected: 'Sem ligação',
  },
  action: {
    reconnecting: 'Tentar agora',
    disconnected: 'Reconectar',
  },
};

extensibilityCode.web:
// A CONTAGEM só existe enquanto alguma tentativa está marcada, e quem
// responde é o vocabulário compartilhado — não um teste escrito na tela.
isRetryScheduled('reconnecting');   // true  → a contagem tem o que contar
isRetryScheduled('disconnected');   // false → nada agendado, nada a contar
isRetryScheduled('connected');      // false → nada caiu, nada a contar

// Os dois falsos chegam pelo mesmo caminho e dizem coisas opostas. É a
// palavra do estado que separa os dois, e é por isso que ela é obrigatória.

customizationCode.web:
.nds-connection-state {
  max-inline-size: 32rem;
}

/* O ponto é REFORÇO, e não a pista: a palavra ao lado é o que descreve o
   estado, e é ela que se anuncia. Mexer no ponto não muda o que chega a quem
   ouve — e a pulsação some sozinha sob movimento reduzido, porque a camada de
   token zera a duração. */
.nds-connection-state[data-state="reconnecting"] .nds-connection-state-dot {
  animation: nds-thinking-pulse var(--duration-slow) var(--ease-standard) infinite;
}

