withLabelsCode.web:
// The word for each of the three states, and the action label where it exists.
//
// Online is deliberately left without an action: there is nothing to do here
// about a link that is up. The other two have different names because they do
// different things — one hurries an attempt that is already scheduled, the
// other starts one.
const rotulos = {
  state: {
    connected: 'Online',
    reconnecting: 'Reconnecting',
    disconnected: 'Offline',
  },
  action: {
    reconnecting: 'Try now',
    disconnected: 'Reconnect',
  },
};

extensibilityCode.web:
// THE COUNTDOWN only exists while an attempt is scheduled, and the shared
// vocabulary is what answers that — not a check written on the screen.
isRetryScheduled('reconnecting');   // true  → the countdown has something to count
isRetryScheduled('disconnected');   // false → nothing scheduled, nothing to count
isRetryScheduled('connected');      // false → nothing dropped, nothing to count

// The two falses arrive by the same path and mean opposite things. It is the
// word of the state that tells them apart, and that is why it is required.

customizationCode.web:
.nds-connection-state {
  max-inline-size: 32rem;
}

/* The dot is REINFORCEMENT, not the clue: the word beside it is what describes
   the state, and it is the word that gets announced. Touching the dot changes
   nothing for whoever listens — and the pulse disappears on its own under
   reduced motion, because the token layer zeroes the duration. */
.nds-connection-state[data-state="reconnecting"] .nds-connection-state-dot {
  animation: nds-thinking-pulse var(--duration-slow) var(--ease-standard) infinite;
}

