extensibilityCode.web:
// LA CUENTA solo existe mientras hay un intento agendado, y quien responde es
// el vocabulario compartido — no una comprobación escrita en la pantalla.
isRetryScheduled('reconnecting');   // true  → la cuenta tiene algo que contar
isRetryScheduled('disconnected');   // false → nada agendado, nada que contar
isRetryScheduled('connected');      // false → nada se cayó, nada que contar

// Los dos falsos llegan por el mismo camino y dicen cosas opuestas. Es la
// palabra del estado la que los separa, y por eso es obligatoria.

customizationCode.web:
